<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\ProjectionSettingsService;use App\Services\LiveDisplaySessionService;Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$s=$pdo->prepare("SELECT r.*,e.name event_name FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id LIMIT 1");$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Round not found.');}$eventId=(int)$round['event_id'];$settings=ProjectionSettingsService::get($pdo,$roundId,false);$notice=$_SESSION['projection_settings_notice']??'';unset($_SESSION['projection_settings_notice']);$token='';if($_SERVER['REQUEST_METHOD']==='POST'&&Csrf::verify($_POST['_csrf']??null)){if(($_POST['action']??'')==='generate_live'){$token=LiveDisplaySessionService::generate($pdo,$eventId,false,(int)(Auth::user()['id']??0));$notice='Live Display link generated. Give this one link to the projector operator.';}elseif(isset($_POST['screen_type'])){if(!LiveDisplaySessionService::forEvent($pdo,$eventId,false))$token=LiveDisplaySessionService::generate($pdo,$eventId,false,(int)(Auth::user()['id']??0));LiveDisplaySessionService::update($pdo,$eventId,false,$_POST,(int)(Auth::user()['id']??0));$notice='Live projector updated.';}}$session=LiveDisplaySessionService::forEvent($pdo,$eventId,false);$stage=ucfirst((string)$round['round_type']);$types=$round['round_type']==='heats'?['judges'=>'Judges','competitors'=>'Competitors','scoring'=>'Scoring Status','callbacks'=>'Callback Reveal']:($round['round_type']==='semifinal'?['judges'=>'Judges','competitors'=>'Semifinal Competitors','scoring'=>'Scoring Status','finalists'=>'Finalists Reveal']:['judges'=>'Judges','competitors'=>'Finalists / Couples','scoring'=>'Scoring Status','results'=>'Final Ranking','winners'=>'Winner Podium']);$formats=['16:9'=>'16:9 Landscape','9:16'=>'9:16 Portrait','4:3'=>'4:3 Standard','16:10'=>'16:10 Landscape','21:9'=>'21:9 Ultra-wide','32:9'=>'32:9 Super-wide','1:1'=>'1:1 Square','custom'=>'Custom Resolution'];$displayUrl=$token!==''?url('live-display/?token='.rawurlencode($token)):'';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Screen Control | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.card{border:0;border-radius:15px}.settings{border-left:5px solid #dc3545}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">Live Screen Projector</a><a class="btn btn-outline-light btn-sm" href="../scoring/?mode=<?=e((string)($round['scoring_mode']??'manual'))?>&round_id=<?=$roundId?>">Back to Scoring</a></div></nav><main class="container py-4"><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><div class="mb-4"><div class="text-uppercase text-danger fw-bold small"><?=e(strtoupper($stage))?> LIVE SCREEN CONTROL</div><h1 class="h2 mb-1"><?=e($round['event_name'])?></h1><div class="text-muted"><?=e(ucwords(str_replace('_',' ',$round['division'])))?> · <?=e($stage)?></div></div><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h5">Projector Live Feed Link</h2><?php if($displayUrl):?><div class="input-group"><input id="liveUrl" class="form-control" readonly value="<?=e($displayUrl)?>"><button type="button" class="btn btn-outline-primary" onclick="navigator.clipboard.writeText(liveUrl.value)">Copy Link</button><a target="_blank" class="btn btn-primary" href="<?=e($displayUrl)?>">Open Preview</a></div><?php elseif($session):?><div class="alert alert-secondary mb-2">A Live Display session already exists. Regenerate the link if you need a new shareable URL.</div><?php else:?><p class="text-muted">Generate one link. The projector operator opens it once and leaves it full-screen.</p><?php endif;?><form method="post" class="mt-2"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><button class="btn btn-dark" name="action" value="generate_live">Generate / Regenerate Live Display Link</button></form></div></div><form class="card settings shadow-sm mb-4" method="post" action="settings.php"><div class="card-body"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="data_mode" value="real"><h2 class="h5">Screen & Layout</h2><div class="row g-2"><div class="col-md-4"><label class="form-label">Screen Format</label><select id="format" name="screen_format" class="form-select"><?php foreach($formats as $v=>$l):?><option value="<?=e($v)?>" <?=$settings['screen_format']===$v?'selected':''?>><?=e($l)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Density</label><select name="density" class="form-select"><option value="maximum" <?=$settings['density']==='maximum'?'selected':''?>>Maximum Density</option><option value="auto" <?=$settings['density']==='auto'?'selected':''?>>Auto</option><option value="large" <?=$settings['density']==='large'?'selected':''?>>Large Cards</option></select></div><div class="col-md-2"><label class="form-label">Custom Width</label><input id="cw" name="custom_width" class="form-control" type="number" min="100" value="<?=e((string)($settings['custom_width']??''))?>"></div><div class="col-md-2"><label class="form-label">Custom Height</label><input id="ch" name="custom_height" class="form-control" type="number" min="100" value="<?=e((string)($settings['custom_height']??''))?>"></div></div><div class="d-flex gap-2 mt-3"><button class="btn btn-danger" name="action" value="apply">Apply Screen Settings</button><button class="btn btn-outline-secondary" name="action" value="reset">Reset to 16:9</button></div></div></form><form method="post" class="card shadow-sm"><div class="card-body"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><h2 class="h5">Live Feed Remote Control</h2><div class="d-flex flex-wrap gap-2 mb-3"><button class="btn btn-outline-dark" name="screen_type" value="holding">Holding Screen</button><?php foreach($types as $v=>$l):?><button class="btn <?=($session['screen_type']??'')===$v?'btn-danger':'btn-outline-danger'?>" name="screen_type" value="<?=e($v)?>"><?=e($l)?></button><?php endforeach;?></div><div class="row g-2"><div class="col-md-3"><label class="form-label">Page</label><input class="form-control" name="page_number" type="number" min="1" value="<?=(int)($session['page_number']??1)?>"></div><div class="col-md-3"><label class="form-label">Auto Page</label><select class="form-select" name="auto_page"><option value="1" <?=!isset($session['auto_page'])||$session['auto_page']?'selected':''?>>On</option><option value="0" <?=isset($session['auto_page'])&&!$session['auto_page']?'selected':''?>>Off</option></select></div><div class="col-md-3"><label class="form-label">Page Delay</label><select class="form-select" name="page_delay_seconds"><?php foreach([10,15,30,45,60] as $d):?><option value="<?=$d?>" <?=($session['page_delay_seconds']??30)===$d?'selected':''?>><?=$d?> seconds</option><?php endforeach;?></select></div></div><div class="small text-muted mt-2">Auto Page defaults to 30 seconds and applies to multi-page Competitors, Callbacks and Finalists.</div></div></form></main><script>function cs(){const on=document.querySelector('#format').value==='custom';cw.disabled=!on;ch.disabled=!on}format.addEventListener('change',cs);cs();</script></body></html>